//! Exceptions passed across contract calls.

use super::Exn;
use super::{LibraryExn, SyscallExn};
#[cfg(feature = "debugging")]
use crate::AbortInfo;
use crate::call::CallError;
use crate::sys::{SyscallErrorCode, SyscallNo};
use crate::xdr::*;
use core::any::Any;
use core::convert::Infallible;
#[cfg(feature = "debugging")]
use core::error::Error;
#[cfg(feature = "debugging")]
use core::fmt::Display;
#[cfg(feature = "debugging")]
use core::fmt::Write;
use core::fmt::{self, Debug};
#[cfg(feature = "debugging")]
use thiserror::Error;

/// An exception generated by a contract or by SDK library code, and then
/// serialized for passing to [`contract_abort`][crate::contract_abort].
///
/// When a contract invocation wishes to abort, it may provide context data in
/// a byte-buffer passed to the [`contract_abort`][crate::contract_abort]
/// syscall. The type of this data must be known in order for the caller to
/// decode it.  Contract methods wrapped by the SDK use `CrossExn<E>`, where
/// `E` is particular to the contract and other exception types known to the
/// SDK may also be represented. Dynamically-typed values passed to `abort()`
/// are downcasted and wrapped in `CrossExn`.
///
#[derive(PartialEq, ReadXDR, WriteXDR)]
pub struct CrossExn<E = Infallible>
where
    E: Exn,
{
    exn: Inner<E>,

    #[cfg(feature = "debugging")]
    location: Option<LocationString>,

    #[cfg(feature = "debugging")]
    backtrace: Option<BacktraceString>,
}

#[cfg(feature = "debugging")]
type LocationString = heapless::String<200>;

#[cfg(feature = "debugging")]
type BacktraceString = heapless::String<500>;

impl<E> Debug for CrossExn<E>
where
    E: Exn,
{
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        #[cfg(feature = "debugging")]
        display_error(&self.exn, f)?;

        #[cfg(not(feature = "debugging"))]
        Debug::fmt(&self.exn, f)?;

        #[cfg(feature = "debugging")]
        if let Some(loc) = self.location.as_ref() {
            write!(f, " at {}", loc)?;
        }

        #[cfg(feature = "debugging")]
        if let Some(bt) = self.backtrace.as_ref()
            && !bt.is_empty()
        {
            write!(f, "\nContext:\n{}", bt)?;
        }

        Ok(())
    }
}

#[cfg(feature = "debugging")]
fn display_error(err: &dyn Error, f: &mut fmt::Formatter) -> fmt::Result {
    fn more(err: &dyn Error, f: &mut fmt::Formatter, n: usize) -> fmt::Result {
        for _ in 0..n {
            write!(f, "  ")?;
        }
        if n > 0 {
            write!(f, "-> ")?;
        }
        writeln!(f, "{}", err)?;

        if let Some(err) = err.source() {
            more(err, f, n + 1)?;
        }

        Ok(())
    }

    more(err, f, 1)
}

// Delegate Display::fmt to &self.exn
#[cfg(feature = "debugging")]
impl<E> Display for CrossExn<E>
where
    E: Exn,
{
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        Display::fmt(&self.exn, f)
    }
}

// Delegate Error::source to &self.exn
#[cfg(feature = "debugging")]
impl<E> Error for CrossExn<E>
where
    E: Exn + 'static,
{
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        self.exn.source()
    }
}

impl<E> CrossExn<E>
where
    E: Exn,
{
    #[cfg(feature = "debugging")]
    pub fn from_abort_info<'a>(info: AbortInfo<'a>) -> Self
    where
        E: Clone + 'static,
    {
        let exn = Inner::from_any(info.payload());
        let backtrace = info.backtrace().map(|bt| format(&bt));
        let location = Some(format(info.location()));

        Self {
            exn,
            backtrace,
            location,
        }
    }

    // An error resulting from a contract-call
    pub fn from_call_err<CE: Exn>(err: CallError<CE>) -> Self {
        let exn = Inner::Library(LibraryExn::Called(err.into_fault_string()));

        #[cfg(feature = "debugging")]
        {
            Self {
                exn,
                backtrace: None,
                location: None,
            }
        }

        #[cfg(not(feature = "debugging"))]
        Self { exn }
    }

    #[cfg(feature = "debugging")]
    pub fn location(&self) -> Option<&LocationString> {
        self.location.as_ref()
    }

    #[cfg(feature = "debugging")]
    pub fn backtrace(&self) -> Option<&BacktraceString> {
        self.backtrace.as_ref()
    }

    pub fn is_unknown(&self) -> bool {
        matches!(&self.exn, Inner::Unknown)
    }

    pub fn as_library_exn(&self) -> Option<&LibraryExn> {
        match &self.exn {
            Inner::Library(exn) => Some(exn),
            _ => None,
        }
    }

    pub fn as_syscall_exn(&self) -> Option<&SyscallExn> {
        self.as_library_exn().and_then(|e| e.as_syscall_exn())
    }

    pub fn as_contract_exn(&self) -> Option<&E> {
        match &self.exn {
            Inner::Contract(exn) => Some(exn),
            _ => None,
        }
    }

    pub fn is_syscall_exn(
        &self,
        call_no: SyscallNo,
        err_code: SyscallErrorCode,
    ) -> bool {
        self.as_library_exn()
            .and_then(|e| e.as_syscall_exn())
            .map(|e| e.is(call_no, err_code))
            .unwrap_or(false)
    }

    /// Serialize an abort payload directly into the `Inner` wire format,
    /// by borrowing the payload rather than cloning it.
    ///
    /// This performs the same three-way downcast dispatch as
    /// `Inner::from_any`, but serializes each variant by reference
    /// instead of cloning into an owned `Inner`. The two must be kept
    /// in sync.
    ///
    pub fn serialize_abort(payload: &dyn Any) -> !
    where
        E: 'static,
    {
        use crate::call::internal::contract_call_encode;
        use crate::exn::encoding_abort_abort;

        // When debugging is enabled, CrossExn has location and backtrace
        // fields after the Inner payload. We write None for both since
        // we don't have caller location info on the borrow path.
        #[cfg(feature = "debugging")]
        let debug_suffix: (
            Option<&LocationString>,
            Option<&BacktraceString>,
        ) = (None, None);

        #[cfg(not(feature = "debugging"))]
        fn encode_variant<T: WriteXDR>(
            discriminant: i32,
            payload: &T,
        ) -> WriteResult<crate::call::internal::EncodeBuf> {
            contract_call_encode(&(discriminant, payload))
        }

        let buf = if let Some(e) = payload.downcast_ref::<E>() {
            //
            // We got an abort value of the expected type.
            //
            #[cfg(not(feature = "debugging"))]
            {
                encode_variant(INNER_CONTRACT, e)
            }
            #[cfg(feature = "debugging")]
            contract_call_encode(&(
                INNER_CONTRACT,
                e,
                debug_suffix.0,
                debug_suffix.1,
            ))
        } else if let Some(e) = payload.downcast_ref::<LibraryExn>() {
            //
            // The SDK library aborted.
            //
            #[cfg(not(feature = "debugging"))]
            {
                encode_variant(INNER_LIBRARY, e)
            }
            #[cfg(feature = "debugging")]
            contract_call_encode(&(
                INNER_LIBRARY,
                e,
                debug_suffix.0,
                debug_suffix.1,
            ))
        } else {
            //
            // Something else!
            //
            #[cfg(not(feature = "debugging"))]
            {
                contract_call_encode(&INNER_UNKNOWN)
            }
            #[cfg(feature = "debugging")]
            contract_call_encode(&(
                INNER_UNKNOWN,
                debug_suffix.0,
                debug_suffix.1,
            ))
        };

        let buf = buf.unwrap_or_else(|e| encoding_abort_abort(e));

        crate::contract_abort(buf.as_ref());
    }
}

#[cfg(feature = "debugging")]
fn format<T, const N: usize>(v: &T) -> heapless::String<N>
where
    T: Display,
{
    let mut s = heapless::String::<N>::new();

    write!(&mut s, "{}", v).unwrap(); // XXX

    s
}

// Private structure
#[derive(Debug, PartialEq, ReadXDR, WriteXDR)]
#[cfg_attr(feature = "debugging", derive(Error))]
#[repr(i32)]
enum Inner<E = Infallible>
where
    E: Exn,
{
    #[cfg_attr(feature = "debugging", error(transparent))]
    Contract(E) = INNER_CONTRACT,

    #[cfg_attr(feature = "debugging", error(transparent))]
    Library(LibraryExn) = INNER_LIBRARY,

    #[cfg_attr(feature = "debugging", error("Unknown error"))]
    Unknown = INNER_UNKNOWN,
}

// Discriminant constants for Inner's repr(i32) variants.
// Used both by the enum itself and by serialize_abort.
const INNER_CONTRACT: i32 = 0;
const INNER_LIBRARY: i32 = 1;
const INNER_UNKNOWN: i32 = 2;

#[cfg(feature = "debugging")]
impl<E: Exn> Inner<E> {
    /// Make a `CrossExn` from a dynamically-typed value.
    ///
    /// We can handle:
    /// - An expected exception-type `E` specified by the caller.
    /// - A "library" exception from this SDK.
    ///
    /// NOTE: The downcast dispatch here must be kept in sync with
    /// `CrossExn::serialize_abort`, which performs the same three-way
    /// dispatch but serializes by reference instead of cloning.
    ///
    pub fn from_any(payload: &dyn Any) -> Self
    where
        E: Clone + 'static,
    {
        if let Some(e) = payload.downcast_ref::<E>() {
            //
            // We got an abort value of the expected type.
            //
            Self::Contract(e.clone())
        } else if let Some(e) = payload.downcast_ref::<LibraryExn>() {
            //
            // The SDK library aborted.
            //
            Self::Library(e.clone())
        } else {
            //
            // Something else!
            //
            Self::Unknown
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::call::internal::contract_call_encode;
    use crate::exn::library::SyscallExn;
    use crate::sys::{SysErr, SyscallNo};

    /// Verify that the manual encoding used by serialize_abort produces
    /// the same wire format as the derive(WriteXDR) on Inner/CrossExn.
    // A contract-level exception type for testing the Contract variant
    #[derive(Debug, Clone, PartialEq, ReadXDR, WriteXDR, thiserror::Error)]
    #[repr(i32)]
    enum TestExn {
        #[error("boom")]
        Boom = 1,
    }

    #[test]
    fn serialize_abort_matches_derive_for_contract_exn() {
        let exn = TestExn::Boom;

        let derived = {
            let inner = Inner::<TestExn>::Contract(exn.clone());
            cxs::encode(&inner).unwrap()
        };

        let manual = contract_call_encode(&(INNER_CONTRACT, &exn)).unwrap();

        assert_eq!(derived, &manual[..]);
    }

    #[test]
    fn serialize_abort_matches_derive_for_library_exn() {
        let exn = LibraryExn::NonNegativeIntOverflow;

        // Derive path: construct an Inner and encode it
        let derived = {
            let inner = Inner::<Infallible>::Library(exn.clone());
            cxs::encode(&inner).unwrap()
        };

        // Manual path: encode (discriminant, payload) tuple
        let manual = contract_call_encode(&(INNER_LIBRARY, &exn)).unwrap();

        assert_eq!(derived, &manual[..]);
    }

    #[test]
    fn serialize_abort_matches_derive_for_syscall_exn() {
        let exn = LibraryExn::Syscall(SyscallExn::new(
            SyscallNo::kBytestringGet,
            SysErr(42),
        ));

        let derived = {
            let inner = Inner::<Infallible>::Library(exn.clone());
            cxs::encode(&inner).unwrap()
        };

        let manual = contract_call_encode(&(INNER_LIBRARY, &exn)).unwrap();

        assert_eq!(derived, &manual[..]);
    }

    #[test]
    fn serialize_abort_matches_derive_for_unknown() {
        let derived = {
            let inner = Inner::<Infallible>::Unknown;
            cxs::encode(&inner).unwrap()
        };

        let manual = contract_call_encode(&INNER_UNKNOWN).unwrap();

        assert_eq!(derived, &manual[..]);
    }

    #[test]
    fn inner_roundtrip_library() {
        // Encode a LibraryExn via the manual path
        let exn = LibraryExn::NonNegativeIntUnderflow;
        let bytes = contract_call_encode(&(INNER_LIBRARY, &exn)).unwrap();

        // Decode as Inner (what serialize_abort writes)
        let decoded: Inner<Infallible> = cxs::decode(&bytes[..]).unwrap();

        assert_eq!(
            decoded,
            Inner::Library(LibraryExn::NonNegativeIntUnderflow)
        );
    }

    #[test]
    fn inner_roundtrip_unknown() {
        let bytes = contract_call_encode(&INNER_UNKNOWN).unwrap();

        let decoded: Inner<Infallible> = cxs::decode(&bytes[..]).unwrap();

        assert_eq!(decoded, Inner::Unknown);
    }
}
